"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """Return the share of sessions whose converted value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """Return the conversion rate pooled across all sessions in all groups."""
    total = converted = 0
    for events in groups.values():
        total += len(events)
        converted += sum(1 for event in events if event["converted"] is True)
    return converted / total if total else 0.0


def conversions_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """Return each group's conversion rate, sorted by group name."""
    return {
        name: conversion_rate(events) if events else None
        for name, events in sorted(groups.items())
    }


def longest_conversion_streak(daily_counts):
    """Return the length of the longest run of positive daily counts."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Product analytics dashboard: parsing and preparing customer sessions."""


def parse_session_log(lines):
    """Parse session log lines into records, reporting malformed lines."""
    out = []
    for line_number, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day_text, converted_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if converted_text == "1":
            converted = True
        elif converted_text == "0":
            converted = False
        elif converted_text == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")
        out.append({"id": id_, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep the last record for each id, sorted by day and then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions for every day in the inclusive range."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day - start_day] += 1
    return counts

"""Product analytics dashboard reporting helpers."""

from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import (
    conversion_rate,
    conversions_in_window,
    pooled_conversion_rate,
)


def campaign_summary(groups, days):
    """Return pooled rate, recent conversions, and nonempty group count."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily = daily_conversion_counts(all_events, first_day, last_day)
        recent = conversions_in_window(daily, days)
    else:
        recent = 0
    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": sum(bool(events) for events in groups.values()),
    }


def top_converting_groups(groups, n):
    """Return up to ``n`` nonempty groups, ranked by rate then name."""
    ranked = [
        (name, conversion_rate(events))
        for name, events in groups.items()
        if events
    ]
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return [name for name, _rate in ranked[:max(n, 0)]]

